//! Bakes the account backend into the app when the build environment names one:
//!
//! ```text
//! TWINCURSOR_BUILD_SUPABASE_URL=https://….supabase.co TWINCURSOR_BUILD_SUPABASE_KEY=… \
//!   cargo build --release -p twincursor-desktop
//! ```
//!
//! Both are public values (the project's URL and its public key), not secrets. They land in a
//! generated file under `OUT_DIR`; `TWINCURSOR_SUPABASE_URL` and `TWINCURSOR_SUPABASE_KEY` at run
//! time override them. Without either, the app has no account features.

use std::fmt::Write as _;

const VARS: [(&str, &str); 2] = [
    ("URL", "TWINCURSOR_BUILD_SUPABASE_URL"),
    ("KEY", "TWINCURSOR_BUILD_SUPABASE_KEY"),
];

fn main() {
    let mut out = String::from("// Generated by build.rs from the build environment.\n");
    for (name, var) in VARS {
        println!("cargo:rerun-if-env-changed={var}");
        let value = std::env::var(var)
            .ok()
            .map(|v| v.trim().to_owned())
            .filter(|v| !v.is_empty());
        let _ = writeln!(out, "pub const {name}: Option<&str> = {value:?};");
    }
    let dir = std::env::var("OUT_DIR").expect("cargo sets OUT_DIR");
    std::fs::write(format!("{dir}/backend.rs"), out).expect("writing backend.rs");

    tauri_build::build()
}
